import { Logging } from "@google-cloud/logging";
import parser from "co-body";
import crypto from "crypto";

const LINEAR_API = "https://api.linear.app/graphql";

// API keys come from BuildShip's native credential selector.
const getAuthorization = async (_inputs = {}, { auth } = {}) => {
  if (typeof auth?.getKey !== "function") {
    throw new Error("Select a Linear API key in the trigger's API Key dropdown.");
  }
  const apiKey = await auth.getKey();
  if (typeof apiKey !== "string" || !apiKey.trim()) {
    throw new Error("Select a Linear API key in the trigger's API Key dropdown.");
  }
  return apiKey.trim();
};

const getAction = (inputs = {}) => {
  const action = inputs.action?.value ?? inputs.action ?? "all";
  if (!["all", "create", "update", "remove", "statusChanged"].includes(action)) {
    throw new Error("Select a valid action from the Action dropdown.");
  }
  return action;
};

const RESOURCE_TYPES = [
  "Issue", "Comment", "IssueLabel", "Project",
  "ProjectUpdate", "Cycle", "Reaction",
];

const getResourceTypes = (value) => {
  let selected = value;
  if (selected == null || selected === "") return ["Issue"];
  if (typeof selected === "string") {
    const text = selected.trim();
    if (text.startsWith("[")) {
      try {
        selected = JSON.parse(text);
      } catch {
        throw new Error("Resource Types contains invalid JSON. Select values from the dropdown.");
      }
    } else {
      selected = text.split(",");
    }
  }
  if (!Array.isArray(selected)) {
    throw new Error("Select Resource Types from the dropdown.");
  }
  const types = [...new Set(selected.map((item) => {
    const type = item?.value ?? item;
    if (typeof type !== "string" || !RESOURCE_TYPES.includes(type.trim())) {
      throw new Error(`Invalid Resource Types selection. Choose: ${RESOURCE_TYPES.join(", ")}.`);
    }
    return type.trim();
  }))];
  if (!types.length) throw new Error("Select at least one Resource Type.");
  return types;
};

// Keep field constraints from Linear's extensions, without echoed credentials,
// input values, validation targets, or server stack traces.
const describeErrors = (errors, authorization, variables) => {
  const privateValues = [authorization];
  const collectSecrets = (value) => {
    if (!value || typeof value !== "object") return;
    for (const [key, item] of Object.entries(value)) {
      if (/secret|token|password|authorization|api.?key/i.test(key) && typeof item === "string" && item) {
        privateValues.push(item);
      } else if (item && typeof item === "object") {
        collectSecrets(item);
      }
    }
  };
  collectSecrets(variables);
  const clean = (value, depth = 0) => {
    if (depth > 12) return "[omitted]";
    if (typeof value === "string") {
      let result = value;
      for (const secret of privateValues.filter(Boolean)) {
        result = result.split(secret).join("[redacted]");
      }
      return result.replace(/lin_api_[A-Za-z0-9_-]+/g, "[redacted]");
    }
    if (Array.isArray(value)) return value.map((item) => clean(item, depth + 1));
    if (!value || typeof value !== "object") return value;
    return Object.fromEntries(Object.entries(value)
      .filter(([key]) => !/^(target|value|stack|stacktrace)$/i.test(key))
      .map(([key, item]) => [key,
        /secret|token|password|authorization|api.?key/i.test(key)
          ? "[redacted]" : clean(item, depth + 1),
      ]));
  };
  return errors.map((error) => {
    const safe = clean(error);
    const code = safe.extensions?.code;
    const details = { path: safe.path, extensions: safe.extensions };
    return `${safe.message || "GraphQL request failed"}${code ? ` [${code}]` : ""}; details: ${JSON.stringify(details)}`;
  }).join("; ").slice(0, 12000);
};

// Linear personal API keys are sent without a Bearer prefix.
const linearGraphQL = async (
  authorization,
  query,
  variables = {},
  timeoutMs = 10000
) => {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(LINEAR_API, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: authorization,
      },
      body: JSON.stringify({ query, variables }),
      signal: controller.signal,
    });

    let json;

    try {
      json = await res.json();
    } catch (err) {
      throw new Error(
        `Linear API returned a non-JSON response (HTTP ${res.status})`
      );
    }

    if (!res.ok || json.errors?.length) {
      const message = Array.isArray(json?.errors) && json.errors.length
        ? describeErrors(json.errors, authorization, variables)
        : `HTTP ${res.status}`;
      const operation = query.match(/(?:mutation|query)\s+(\w+)/)?.[1] || "request";
      throw new Error(
        `Linear API error (HTTP ${res.status}, ${operation}): ${message}`
      );
    }

    if (!json.data) {
      throw new Error("Linear returned no GraphQL data.");
    }

    return json.data;
  } finally {
    clearTimeout(timer);
  }
};

const WEBHOOK_CREATE = `
  mutation CreateWebhook($input: WebhookCreateInput!) {
    webhookCreate(input: $input) {
      success
      webhook {
        id
        secret
        url
        label
        enabled
        resourceTypes
      }
    }
  }
`;

const WEBHOOK_UPDATE = `
  mutation UpdateWebhook($id: String!, $input: WebhookUpdateInput!) {
    webhookUpdate(id: $id, input: $input) {
      success
      webhook {
        id
        url
        label
        enabled
        resourceTypes
      }
    }
  }
`;

const WEBHOOK_DELETE = `
  mutation DeleteWebhook($id: String!) {
    webhookDelete(id: $id) {
      success
    }
  }
`;

const WEBHOOK_SECRET = `
  query WebhookSigningSecret($id: String!) {
    webhook(id: $id) {
      id
      secret
    }
  }
`;

const onDeploy = async (inputs = {}, context = {}) => {
  const { resourceTypes, linearTeamId, webhookLabel } = inputs;
  const { workflow, workflowId, runtimeUrl, env, trigger } = context;

  console.log("[Linear trigger] Registration started");

  try {
    // BuildShip documents workflow.id.
    // Keep workflowId as a compatibility fallback.
    const id = workflow?.id || workflowId;

    if (typeof id !== "string" || !id.trim() ||
        typeof trigger?.id !== "string" || !trigger.id.trim() ||
        typeof runtimeUrl !== "string" || !runtimeUrl.trim()) {
      throw new Error(
        "Missing BuildShip workflow.id, trigger.id, or runtimeUrl."
      );
    }

    const base = new URL(runtimeUrl.trim());
    if (base.protocol !== "https:" || base.hostname === "localhost" ||
        base.hostname.endsWith(".localhost") || base.hostname === "127.0.0.1" ||
        base.hostname === "[::1]" || base.username || base.password || base.search || base.hash) {
      throw new Error(
        "Linear requires a publicly accessible HTTPS webhook URL."
      );
    }
    const webhookUrl =
      `${base.href.replace(/\/+$/, "")}` +
      `/executeWorkflow/${encodeURIComponent(id.trim())}/${encodeURIComponent(trigger.id.trim())}`;

    const apiKey = await getAuthorization(inputs, context);
    const selectedAction = getAction(inputs);

    const types = getResourceTypes(resourceTypes);
    if (selectedAction === "statusChanged" && !types.includes("Issue")) {
      throw new Error("Select Issue in Resource Types to use Issue status changed.");
    }
    if (webhookLabel != null && typeof webhookLabel !== "string") {
      throw new Error("Webhook Label must be text.");
    }
    if (linearTeamId != null && typeof linearTeamId !== "string") {
      throw new Error("Team ID must be a Linear team UUID or key, or left empty for all public teams.");
    }
    const label = webhookLabel?.trim() || "BuildShip Workflow";
    const teamId = linearTeamId?.trim();

    const existingId = env.get("linearWebhookId");
    let existingSecret = env.get("linearWebhookSecret");

    if (existingId && !existingSecret) {
      const data = await linearGraphQL(apiKey, WEBHOOK_SECRET, { id: existingId });
      existingSecret = data?.webhook?.secret;
      if (typeof existingSecret !== "string" || !existingSecret) {
        throw new Error("Stored Linear webhook has no available signing secret. Copy its signing secret from Linear into linearWebhookSecret and reconnect.");
      }
      await env.set([{ name: "linearWebhookSecret", value: existingSecret }]);
    }

    // Reuse the endpoint and secret when updating an existing webhook.
    if (existingId && existingSecret) {
      console.log("[Linear trigger] Updating existing webhook");

      try {
        const data = await linearGraphQL(apiKey, WEBHOOK_UPDATE, {
          id: existingId,
          input: {
            url: webhookUrl,
            resourceTypes: types,
            label,
            enabled: true,
          },
        });

        if (
          data?.webhookUpdate?.success !== true ||
          !data.webhookUpdate.webhook?.id
        ) {
          throw new Error(
            "Linear did not confirm the webhook update."
          );
        }

        console.log("[Linear trigger] Webhook updated");

        return {
          success: true,
          message: "Webhook updated successfully",
        };
      } catch (error) {
        // Authentication, permissions, and network failures
        // do not prove that the existing webhook was deleted.
        throw new Error(
          `Could not update the stored Linear webhook: ${error.message}. ` +
          "If it was deleted in Linear, clear linearWebhookId and " +
          "linearWebhookSecret in this workflow's environment, " +
          "then reconnect."
        );
      }
    }

    // Let Linear generate the signing secret, as in its official API example.
    const input = {
      url: webhookUrl,
      resourceTypes: types,
      label,
    };

    if (teamId) {
      input.teamId = teamId;
    } else {
      input.allPublicTeams = true;
    }
    console.log("[Linear trigger] Creating webhook");

    const data = await linearGraphQL(apiKey, WEBHOOK_CREATE, {
      input,
    });

    const webhook = data?.webhookCreate?.webhook;

    if (
      data?.webhookCreate?.success !== true ||
      !webhook?.id
    ) {
      throw new Error(
        "Linear did not confirm creation or return a webhook id."
      );
    }

    const secret = webhook.secret;
    if (typeof secret !== "string" || !secret) {
      // Remember the created webhook so reconnecting cannot create a duplicate.
      await env.set([{ name: "linearWebhookId", value: webhook.id }]);
      throw new Error("Linear created the webhook but did not return a signing secret. Reconnect to retrieve it, or copy it from Linear into linearWebhookSecret.");
    }

    await env.set([
      {
        name: "linearWebhookSecret",
        value: secret,
      },
      {
        name: "linearWebhookId",
        value: webhook.id,
      },
    ]);
    console.log("[Linear trigger] Webhook created");

    return {
      success: true,
      message: "Webhook created successfully",
    };
  } catch (error) {
    const message =
      `Linear webhook registration failed: ${error.message}`;

    console.error(message);

    // Throw so a failed registration cannot be mistaken for success.
    throw new Error(message);
  }
};

const STATE_LOOKUP = `
  query StateNames($previousId: String!) {
    previous: workflowState(id: $previousId) {
      id
      name
      type
      color
      position
    }
  }
`;

const STATE_LOOKUP_BOTH = `
  query StateNames($previousId: String!, $currentId: String!) {
    previous: workflowState(id: $previousId) {
      id
      name
      type
      color
      position
    }
    current: workflowState(id: $currentId) {
      id
      name
      type
      color
      position
    }
  }
`;

const onExecution = async (inputs = {}, context = {}) => {
  const { resolveStateNames } = inputs;
  const { req, request, logging, env, nodeReq, terminate } = context;
  const selectedAction = getAction(inputs);

  const reject = (status, message) => {
    logging.error(message);

    if (typeof req?.throw === "function") {
      req.throw(status, message);
    }

    const error = new Error(message);
    error.status = status;
    throw error;
  };

  const secret = env.get("linearWebhookSecret");

  if (!secret) {
    reject(
      500,
      "linearWebhookSecret not found. " +
      "Connect the trigger successfully first."
    );
  }

  // Prefer raw bytes retained by upstream middleware.
  // Never re-stringify parsed JSON for signature verification.
  const savedRaw =
    nodeReq?.rawBody ??
    request?.rawBody ??
    req?.request?.rawBody;

  let raw;
  let parsed;

  if (
    typeof savedRaw === "string" ||
    Buffer.isBuffer(savedRaw)
  ) {
    raw = savedRaw;
  } else {
    if (!nodeReq || nodeReq.readableEnded) {
      reject(
        500,
        "Raw webhook body is unavailable for signature verification."
      );
    }

    const body = await parser["json"](nodeReq, {
      returnRawBody: true,
    });

    raw = body.raw;
    parsed = body.parsed;
  }

  const headers =
    request?.headers ??
    req?.request?.headers ??
    nodeReq?.headers;

  const signature =
    typeof headers?.get === "function"
      ? headers.get("linear-signature")
      : headers?.["linear-signature"] ??
        headers?.["Linear-Signature"];

  if (
    typeof signature !== "string" ||
    !/^[a-fA-F0-9]{64}$/.test(signature)
  ) {
    reject(401, "Missing or invalid linear-signature header");
  }

  const expectedBuf = crypto
    .createHmac("sha256", secret)
    .update(raw)
    .digest();

  const receivedBuf = Buffer.from(signature, "hex");

  if (
    expectedBuf.length !== receivedBuf.length ||
    !crypto.timingSafeEqual(expectedBuf, receivedBuf)
  ) {
    reject(401, "Unable to verify Linear signature");
  }

  let event;

  try {
    event = parsed ?? JSON.parse(raw.toString());
  } catch (err) {
    reject(400, `Unable to parse Linear payload: ${err.message}`);
  }

  const timestamp = Number(event?.webhookTimestamp);

  if (
    !Number.isFinite(timestamp) ||
    timestamp <= 0 ||
    Math.abs(Date.now() - timestamp) > 60_000
  ) {
    reject(
      401,
      "Missing, invalid, or stale Linear webhook timestamp"
    );
  }

  // Detect issue status changes using the previous stateId.
  const statusChanged =
    event?.type === "Issue" &&
    event?.action === "update" &&
    !!event?.updatedFrom &&
    Object.prototype.hasOwnProperty.call(
      event.updatedFrom,
      "stateId"
    );

  const matchesAction =
    selectedAction === "all" ||
    (selectedAction === "statusChanged"
      ? statusChanged
      : event?.action === selectedAction);

  if (!matchesAction) {
    if (typeof terminate !== "function") {
      throw new Error("BuildShip terminate() is required to filter webhook events.");
    }
    // Acknowledge the delivery without starting downstream workflow nodes.
    return terminate(200, "Event does not match the selected action.");
  }

  let previousState = null;
  let currentState = event?.data?.state ?? null;

  if (statusChanged && resolveStateNames !== false) {
    const previousId = event.updatedFrom.stateId;
    const currentId =
      event?.data?.stateId ?? event?.data?.state?.id;

    if (previousId) {
      try {
        const apiKey = await getAuthorization(inputs, context);
        const needsCurrent = !currentState && !!currentId;

        const data = await linearGraphQL(
          apiKey,
          needsCurrent ? STATE_LOOKUP_BOTH : STATE_LOOKUP,
          needsCurrent
            ? { previousId, currentId }
            : { previousId },
          2000
        );

        previousState = data?.previous ?? null;

        if (needsCurrent) {
          currentState = data?.current ?? currentState;
        }
      } catch (error) {
        // Preserve delivery even if optional name resolution fails.
        logging.error(
          `Failed to resolve workflow state names: ${error.message}`
        );
      }
    }
  }

  const result = {
    ...event,
    statusChanged,
    previousState,
    currentState,
    statusTransition:
      statusChanged &&
      previousState?.name &&
      currentState?.name
        ? `${previousState.name} -> ${currentState.name}`
        : null,
  };

  logging.log("event", result);

  return result;
};

const onDelete = async (inputs = {}, context = {}) => {
  const { env } = context;
  const webhookId = env.get("linearWebhookId");

  if (webhookId) {
    try {
      const apiKey = await getAuthorization(inputs, context);

      const data = await linearGraphQL(
        apiKey,
        WEBHOOK_DELETE,
        { id: webhookId }
      );

      if (data?.webhookDelete?.success !== true) {
        throw new Error(
          "Linear did not confirm webhook deletion."
        );
      }

      await env.delete([
        "linearWebhookId",
        "linearWebhookSecret",
      ]);

      console.log("Webhook deleted successfully");

      return {
        success: true,
        message: "Webhook deleted successfully",
      };
    } catch (error) {
      console.log(`Failed to delete webhook: ${error.message}`);

      throw new Error(
        `Failed to delete Linear webhook: ${error.message}`
      );
    }
  }

  console.log("No webhook to delete");

  return {
    success: true,
    message: "No webhook to delete",
  };
};

const fetchLogEntries = async (
  triggerId,
  retries = 3,
  delay = 1000
) => {
  const projectId = process.env.GCLOUD_PROJECT;
  const logging = new Logging({ projectId });

  const filter =
    `logName="projects/${projectId}/logs/buildship-node-io" ` +
    `AND jsonPayload.nId="${triggerId}"`;

  const options = {
    filter,
    pageSize: 10,
    orderBy: "timestamp desc",
  };

  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const [entries] = await logging.getEntries(options);

      if (entries && entries.length > 0) {
        return entries;
      }

      if (attempt < retries) {
        await new Promise((resolve) =>
          setTimeout(resolve, delay)
        );
      }
    } catch (error) {
      console.error(
        `Attempt ${attempt} failed due to an error:`,
        error
      );

      if (attempt < retries) {
        await new Promise((resolve) =>
          setTimeout(resolve, delay)
        );
      } else {
        throw new Error(
          `Failed to fetch log entries after ${retries} attempts: ` +
          error.message
        );
      }
    }
  }

  throw new Error(
    "No webhook data found. Change an issue in a subscribed " +
    "Linear team, then click Get Data again."
  );
};

const getData = async (inputs, { trigger }) => {
  try {
    const entries = await fetchLogEntries(
      trigger.id,
      5,
      2000
    );

    for (const entry of entries) {
      const jsonLog = entry.toStructuredJSON();

      for (const payload of [
        jsonLog.jsonPayload,
        jsonLog.message,
        entry.data,
      ]) {
        if (
          payload &&
          typeof payload === "object" &&
          Object.prototype.hasOwnProperty.call(payload, "o")
        ) {
          return {
            success: true,
            message: "",
            data: payload.o,
          };
        }
      }
    }

    throw new Error(
      "No trigger output found in recent logs. " +
      "Check the workflow logs for delivery errors."
    );
  } catch (error) {
    return {
      success: false,
      message: error.message,
      data: null,
    };
  }
};

const onResponse = () => ({
  status: 200,
  value: { received: true },
  cacheMaxAge: 0,
});

export default {
  onCreate: onDeploy,
  onUpdate: onDeploy,
  onExecution,
  onResponse,
  onDelete,
  getData,
};
